param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'decimal-create-truncating-floating-carriers-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$definition=@([decimal].GetMethods([Reflection.BindingFlags]'Public,Static')|Where-Object {$_.Name -eq 'CreateTruncating' -and $_.IsGenericMethodDefinition});if($definition.Count -ne 1){throw 'One generic CreateTruncating definition required'};$rows=[Collections.Generic.List[object]]::new()
foreach($property in $plan.rawBits.PSObject.Properties){$native=[type]::GetType($property.Name,$true);$closed=$definition[0].MakeGenericMethod([type[]]@($native));for($index=0;$index -lt $property.Value.Count;$index++){$hex=$property.Value[$index];if($property.Name -eq 'System.Single'){$value=[BitConverter]::ToSingle([BitConverter]::GetBytes([Convert]::ToUInt32($hex,16)),0)}else{$value=[BitConverter]::ToDouble([BitConverter]::GetBytes([Convert]::ToUInt64($hex,16)),0)};if($value.GetType() -ne $native){throw 'Input type mismatch'};try{$actual=[decimal]$closed.Invoke($null,[object[]]@($value));$result=[ordered]@{ok=$true;bits=[decimal]::GetBits($actual)}}catch{$result=Failure $_};$rows.Add([ordered]@{type=$property.Name;index=$index;rawBits=$hex;result=$result})}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS Decimal CreateTruncating integer/Decimal: $($rows.Count) native calls"
